		{
			base.update();
			FlxG.collide<Hans, FlxSprite>(player, blocks, blockCollision);
			if (player.y > 320)
			{
				instantDeath();
			}
		}

		public override void getWell()
		{
			FlxG.bgColor = 4288900388;
		}

		public override void nextLevel()
		{
			FlxG.switchState(new Level35second());
		}

		public override void addBgDetail()
		{
			bgDetails[1][0] = "bird";
			bgDetails[2][0] = "bird2";
			bgDetails[6][0] = "windowPalm";
		}
	}
}
